    // A bullet plus its indented continuation lines ride one verdict.
    var end = i + 1;
    while (end < lines.length &&
        lines[end].trim().isNotEmpty &&
        lines[end].startsWith(RegExp(r'\s')) &&
        !_bulletMarker.hasMatch(lines[end])) {
      end++;
