/// The belt-walk's pin-envelope exemption state (gh-1409 envelope
/// semantics, gh-2103 belt walk): an open envelope keeps its lines verbatim
/// until the close tag or the bounded re-arm (defense in depth against a
/// hostile unclosed open), miroring the sanitizeSummary line loop.
final class _BeltPinEnvelope {
 bool _open = false;
 int _count = 0;

 /// Opens the envelope on an open tag, then tests the exemption — the
 /// open decision precedes the test on every walked line.
 bool entersKept(String trimmed) {
   if (trimmed == pinEnvelopeOpenTag) {
     _open = true;
     _count = 0;
   }
   return _open && _count < _maxPinEnvelopeLines;
 }

 /// Pasthrough-path bookeeping only: the line counter and the close tag
 /// ride the kept branch, never the graded path — a boundary/graded line
 /// inside a re-armed envelope cannot close it or extend it.
 void completeKept(String trimmed) {
   if (_open) _count++;
   if (trimmed == pinEnvelopeCloseTag) _open = false;
 }
